// Crear un Quaternion desde ángulos Euler
Quaternion rot90Y = Quaternion.Euler(0f, 90f, 0f); // 90° en eje Y
Quaternion rot45X = Quaternion.Euler(45f, 0f, 0f); // 45° en eje X

// Asignar rotación directamente
transform.rotation = Quaternion.Euler(0f, 180f, 0f); // media vuelta

// Leer la rotación como Euler (para mostrar en UI)
Vector3 eulerAngles = transform.rotation.eulerAngles;
float yAngle = transform.rotation.eulerAngles.y;

// NO hacer esto en código (causa gimbal lock y comportamiento errático):
// transform.rotation.eulerAngles += new Vector3(0, 1, 0); // MAL
// En su lugar:
transform.Rotate(0f, rotSpeed * Time.deltaTime, 0f);

// SLERP: interpolación esférica entre dos rotaciones
// Produce una rotación suave que sigue el arco más corto en la esfera de rotaciones
Quaternion from = transform.rotation;
Quaternion to = targetRotation;
transform.rotation = Quaternion.Slerp(from, to, speed * Time.deltaTime);

// LERP para rotaciones: interpolación lineal (menos natural para rotaciones grandes)
transform.rotation = Quaternion.Lerp(from, to, t);

// LookRotation: calcular la rotación para mirar hacia una dirección
Vector3 direction = (target.position - transform.position).normalized;
Quaternion lookRot = Quaternion.LookRotation(direction);
transform.rotation = Quaternion.Slerp(transform.rotation, lookRot, rotSpeed * Time.deltaTime);

// Forma directa (instantánea, sin suavizado)
transform.LookAt(target.position);

